  bool sceneCapture=BridgeArena.Active;camera.cullingMask=sceneCapture?~(LayerMask.GetMask("UI")|LayerMask.GetMask("FXCamera")):0;if(sceneCapture&&!sceneCaptureLogged){sceneCaptureLogged=true;InputAction.Instance.Event("CPU_NATIVE_SCENE_CAPTURE empty arena only; alpha0 clear; native meshes sprites particles; UI and FXCamera excluded");}Bounds bounds=new Bounds(R.Player.transform.position+Vector3.up,new Vector3(2,4,1));bool found=false;
  commands.Clear();if(!sceneCapture){commands.SetRenderTarget(rt);commands.ClearRenderTarget(true,true,Color.clear);}
  for(int r=0;r<renderers.Length;r++){Renderer item=renderers[r];if(item==null||!item.enabled||!item.gameObject.activeInHierarchy){activeMaterials[r]=false;continue;}if(!activeMaterials[r]){materials[r]=item.sharedMaterials;meshes[r]=item.GetComponent<MeshFilter>();activeMaterials[r]=true;}MeshFilter mesh=meshes[r];if(!(item is MeshRenderer)||mesh==null||mesh.sharedMesh==null||mesh.sharedMesh.vertexCount==0)continue;if(!found){bounds=item.bounds;found=true;}else bounds.Encapsulate(item.bounds);Material[] mats=materials[r];for(int i=0;i<mats.Length&&i<mesh.sharedMesh.subMeshCount;i++)if(mats[i]!=null&&!sceneCapture)commands.DrawRenderer(item,mats[i],i);}
  if(sceneCapture){var playerBounds=R.Player.gameObject.GetComponent<BoxCollider2D>().bounds;center=playerBounds.center;size=6f;}else{center=bounds.center;size=Mathf.Max(2f,bounds.extents.y*1.25f,bounds.extents.x*1.25f);}camera.transform.position=new Vector3(center.x,center.y,center.z-20);camera.transform.rotation=Quaternion.identity;camera.orthographicSize=size;
